using System;using System.Linq;using KO.HollowKnight8;using UnityEngine;using HutongGames.PlayMaker;using HutongGames.PlayMaker.Actions;using GlobalEnums;using Scenes=UnityEngine.SceneManagement.SceneManager;
class Test {
 static int checks;static void Check(bool v,string s){checks++;if(!v)throw new Exception(s);}
 static PlayerSlot Player(int i){var o=new GameObject("Knight P"+(i+1));var h=o.AddComponent<HeroController>();o.AddComponent<Collider2D>();o.AddComponent<Rigidbody2D>();o.AddComponent<MeshRenderer>();
  h.superDash=o.AddComponent<PlayMakerFSM>();h.superDash.FsmName="Superdash";h.superDash.FsmStates=new[]{new FsmState{Name="Inactive"},new FsmState{Name="Ground Charge"},new FsmState{Name="Dash"}};h.proxyFSM=o.AddComponent<PlayMakerFSM>();h.proxyFSM.FsmName="ProxyFSM";
  var p=new PlayerSlot{Index=i,Hero=h};h.proxyFSM.Sent=evt=>{if(evt!="HeroCtrl-EnterSuperDash")return;h.cState.superDashing=true;h.superDash.ActiveStateName="Dash";var body=h.GetComponent<Rigidbody2D>();body.velocity=new(h.cState.facingRight?30:-30,0);};return p;
 }
 static CoopSession Party(){NativeDashEffects.Clear();CrystalDashTransit.Reset();WeaverlingLifetime.Reset();var s=new CoopSession();for(int i=0;i<8;i++)s.Players.Add(Player(i));s.Primary=s.Players[0];Plugin.Self=new(){Session=s};GameManager.instance=new();return s;}
 static GameObject Child(PlayerSlot p,string name){var o=new GameObject(name);o.transform.parent=p.Hero.transform;return o;}
 static GameObject Spider(PlayerSlot p){var o=new GameObject("Weaverling(Clone)");o.AddComponent<tk2dSpriteAnimator>();o.AddComponent<PlayMakerFSM>();WeaverlingLifetime.Spawned(o,p);return o;}
 static void Main(){Walks();Spiders();ResetAndTransit();Effects();Density();Console.WriteLine("PASS production walk ownership, Weaversong lifetime, native dash reset/transit and FX regressions: "+checks);}
 static void Walks(){var s=Party();int nativeCalls=0;var a=new GameObject("Walk area").AddComponent<WalkArea>();var area=a.gameObject.AddComponent<Collider2D>();
  foreach(var p in s.Players){Hooks.TestEnter(a,p.Hero.GetComponent<Collider2D>(),(_,_)=>nativeCalls++);Check(p.Hero.cState.inWalkZone,"Each player's own entry enables walking");}
  Check(nativeCalls==0,"P1 and all extras bypass WalkArea's singleton cached hero");
  var b=new GameObject("Second walk area").AddComponent<WalkArea>();b.gameObject.AddComponent<Collider2D>();var p1=s.Primary;
  Hooks.TestEnter(b,p1.Hero.GetComponent<Collider2D>(),(_,_)=>nativeCalls++);Hooks.TestExit(a,p1.Hero.GetComponent<Collider2D>(),(_,_)=>nativeCalls++);Check(p1.Hero.cState.inWalkZone,"Leaving one overlapping zone preserves another");
  b.enabled=false;Hooks.TestRefresh(p1);Check(!p1.Hero.cState.inWalkZone,"P1 returns to running when its last walk area is disabled");Check(s.Players[1].Hero.cState.inWalkZone,"P1's exit cannot change another player");
  area.ActualOverlap=false;foreach(var p in s.Players){Hooks.TestRefresh(p);Check(!p.Hero.cState.inWalkZone,"Shape distance rejects a false AABB overlap / teleport away");}
  area.ActualOverlap=true;Hooks.TestStay(a,p1.Hero.GetComponent<Collider2D>(),(_,_)=>nativeCalls++);Check(p1.Hero.cState.inWalkZone,"Stay repairs a missed enter after teleport / join");
  var world=new GameObject().AddComponent<Collider2D>();Hooks.TestEnter(a,world,(_,_)=>nativeCalls++);Check(nativeCalls==0,"Unowned layer-9 contacts cannot slow P1");s.Active=false;Hooks.TestEnter(a,world,(_,_)=>nativeCalls++);Check(nativeCalls==1,"Solo native behavior is forwarded unchanged");s.Active=true;
 }
 static void Spiders(){var s=Party();foreach(var p in s.Players)p.Charms.Equipped[38]=true;var initial=s.Players.Select(p=>new[]{Spider(p),Spider(p),Spider(p)}).ToArray();
  for(int cycle=0;cycle<300;cycle++)foreach(var p in s.Players){p.Charms.Equipped[38]=false;WeaverlingLifetime.Trim(p);Check(!GameObject.all.Any(o=>o.activeInHierarchy&&o.GetComponent<OwnerTag>()?.Player==p),"Unequip removes only that player's spiders immediately");p.Charms.Equipped[38]=true;for(int i=0;i<6;i++)Spider(p);Check(GameObject.all.Count(o=>o.activeInHierarchy&&o.GetComponent<OwnerTag>()?.Player==p)==3,"Repeated equip checks keep one native trio per player");}
  var a=s.Players[0];var b=s.Players[1];var pooled=Spider(a);pooled.SetActive(false);pooled.SetActive(true);WeaverlingLifetime.Spawned(pooled,b);a.Charms.Equipped[38]=false;WeaverlingLifetime.Trim(a);Check(pooled.activeInHierarchy&&pooled.GetComponent<OwnerTag>().Player==b,"Pool reuse follows new owner, not stale tag");
  b.Down=true;WeaverlingLifetime.Trim(b);Check(!pooled.activeInHierarchy,"Downed owner's familiars are cleared without affecting allies");Check(s.Players.Skip(2).All(p=>GameObject.all.Count(o=>o.activeInHierarchy&&o.GetComponent<OwnerTag>()?.Player==p)==3),"Other six players retain their three spiders");
  var projectile=new GameObject("Weaverling projectile");WeaverlingLifetime.Spawned(projectile,s.Players[2]);Check(projectile.activeInHierarchy&&projectile.GetComponent<OwnerTag>()==null,"Unrelated familiar projectile isn't treated as a spider root");WeaverlingLifetime.Reset();Check(!GameObject.all.Any(o=>o.activeInHierarchy&&o.GetComponent<OwnerTag>()!=null),"Room/reset cleanup leaves no old live spiders");
 }
 static TransitionPoint Gate(string name,GatePosition pos){var g=new GameObject(name).AddComponent<TransitionPoint>();g.Position=pos;TransitionPoint.TransitionPoints.Clear();TransitionPoint.TransitionPoints.Add(g);return g;}
 static void ResetAndTransit(){var s=Party();var gm=GameManager.instance;Scenes.Name="Room_A";Gate("left1",GatePosition.left);foreach(var p in s.Players){p.Hero.cState.superDashing=true;p.Hero.cState.freezeCharge=true;p.Hero.superDash.ActiveStateName="Dash";}
  CrystalDashTransit.CaptureVote(s.Players[1],"Room_B");CrystalDashTransit.Prepare(s,s.Players[1],new(){SceneName="Room_B",EntryGateName="left1",HeroLeaveDirection=GatePosition.right});
  Check(s.Primary.Hero.exitedSuperDashing,"P1 entrance retains P1's own captured flight");Scenes.Name="Room_B";
  foreach(var p in s.Players){p.Hero.gameObject.SetActive(true);using(PlayerContext.Enter(p))ActorRecovery.Reset(p);p.Ready=true;Check(!p.Hero.cState.superDashing&&!p.Hero.cState.freezeCharge,"Actual ActorRecovery clears flags omitted by vanilla Reset");}
  gm.IsLoadingSceneTransition=true;CrystalDashTransit.Tick();Check(s.Players.All(p=>!p.Hero.cState.superDashing),"No resume runs during room loading");gm.IsLoadingSceneTransition=false;CrystalDashTransit.Tick();
  foreach(var p in s.Players){Check(p.Hero.cState.superDashing&&p.Hero.superDash.ActiveStateName=="Dash","All eight actors re-enter the real native flight");Check(p.Hero.hero_state==ActorStates.no_input&&!p.Hero.acceptingInput&&!p.Hero.Animation&&p.Hero.GetComponent<Rigidbody2D>().gravityScale==0,"Native entry preconditions prevent ordinary movement / animation overwriting flight");Check(p.Hero.GetComponent<Rigidbody2D>().velocity.x==30&&CrystalDashCoop.Counts[p.Index]==2,"Gate direction and linked damage survive independently");}
  // A stale true flag in Inactive must not short-circuit the native event.
  Scenes.Name="Room_B";CrystalDashTransit.Prepare(s,s.Primary,new(){SceneName="Room_C",EntryGateName="right1",HeroLeaveDirection=GatePosition.left});Scenes.Name="Room_C";Gate("right1",GatePosition.right);
  foreach(var p in s.Players){p.Hero.gameObject.SetActive(true);p.Ready=true;p.Hero.superDash.ActiveStateName="Inactive";p.Hero.RegainControl();}
  CrystalDashTransit.Tick();Check(s.Players.All(p=>p.Hero.GetComponent<Rigidbody2D>().velocity.x==-30&&!p.Hero.acceptingInput),"Stale flags trigger actual resume, including direction reversal");
  // Terrain is not bypassed to preserve a flight; bounded failure restores control.
  Scenes.Name="Room_C";CrystalDashTransit.Prepare(s,s.Primary,new(){SceneName="Room_D",EntryGateName="left1",HeroLeaveDirection=GatePosition.right});Scenes.Name="Room_D";Gate("left1",GatePosition.left);SpawnSafety.Clear=false;
  foreach(var p in s.Players){p.Hero.gameObject.SetActive(true);ActorRecovery.Reset(p);p.Ready=true;}CrystalDashTransit.Tick();Check(s.Players.All(p=>!p.Hero.cState.superDashing&&p.Hero.acceptingInput),"A blocked arrival remains controllable without a flight through terrain");SpawnSafety.Clear=true;
  Scenes.Name="Room_D";s.Primary.Hero.cState.superDashing=true;s.Primary.Hero.superDash.ActiveStateName="Dash";CrystalDashTransit.Prepare(s,s.Primary,new(){SceneName="Room_E",EntryGateName="left1",HeroLeaveDirection=GatePosition.right});Scenes.Name="Room_E";foreach(var p in s.Players){p.Hero.gameObject.SetActive(true);ActorRecovery.Reset(p);p.Ready=true;}
  s.Primary.Hero.proxyFSM.Sent=_=>{};CrystalDashTransit.Tick();Time.unscaledDeltaTime=.5f;CrystalDashTransit.Tick();Check(s.Primary.Hero.acceptingInput&&s.Primary.Hero.Animation,"Unresponsive native event recovers within bounded deadline");Time.unscaledDeltaTime=.1f;
  s.Primary.Hero.cState.superDashing=true;s.Primary.Hero.superDash.ActiveStateName="Dash";CrystalDashTransit.Prepare(s,s.Primary,new(){SceneName="Room_F",EntryGateName="left1",HeroLeaveDirection=GatePosition.right});Scenes.Name="Room_F";foreach(var p in s.Players){p.Hero.gameObject.SetActive(true);ActorRecovery.Reset(p);p.Ready=true;}
  CrystalDashCoop.Counts[0]=0;s.Primary.Hero.proxyFSM.Sent=_=>s.Primary.Hero.cState.superDashing=true;CrystalDashTransit.Tick();Check(CrystalDashCoop.Counts[0]==0,"An event setting only the stale flag cannot claim a successful resume");Time.unscaledDeltaTime=.5f;CrystalDashTransit.Tick();Check(s.Primary.Hero.acceptingInput&&!s.Primary.Hero.cState.superDashing,"A flag-only native response also recovers without a softlock");Time.unscaledDeltaTime=.1f;
  CrystalDashTransit.Reset();Scenes.Name="Room_E";s.Primary.Hero.cState.superDashing=true;CrystalDashTransit.Prepare(s,s.Primary,new(){SceneName="GG_Arena",EntryGateName="left1",HeroLeaveDirection=GatePosition.right});Scenes.Name="GG_Arena";s.Primary.Hero.cState.superDashing=false;CrystalDashTransit.Tick();Check(!s.Primary.Hero.cState.superDashing,"Arenas/cinematics do not acquire accidental flights");
 }
 static void Effects(){var s=Party();var p=s.Primary;var body=p.Hero.GetComponent<MeshRenderer>();
  var charge=Child(p,"Renamed charge ring");var chargeMesh=charge.AddComponent<MeshRenderer>();var chargePS=charge.AddComponent<ParticleSystem>();chargePS.isPlaying=true;
  p.Hero.superDash.FsmStates[1].Actions=new[]{new SetMeshRenderer{gameObject=new(){Object=charge}}};
  var trail=Child(p,"SD Trail");var trailMesh=trail.AddComponent<MeshRenderer>();var trailPS=trail.AddComponent<ParticleSystem>();trailPS.isPlaying=true;
  var burst=Child(p,"SD Burst");var burstMesh=burst.AddComponent<MeshRenderer>();var burstPS=burst.AddComponent<ParticleSystem>();burstPS.isPlaying=true;burstPS.main.loop=false;
  var screen=Child(p,"SD Burst Glow");var glow=screen.AddComponent<MeshRenderer>();var glowPS=screen.AddComponent<ParticleSystem>();glowPS.isPlaying=true;
  NativeDashEffects.Stop(p);Check(body.enabled&&glow.enabled&&glowPS.isPlaying,"Body and screen glow are excluded from native dash cleanup");Check(!chargeMesh.enabled&&!trailMesh.enabled&&!chargePS.isPlaying&&!trailPS.isPlaying&&!burstPS.isPlaying,"Actual charge art, trail and one-shot leftovers are cleaned");
  p.Hero.superDash.ActiveStateName="Ground Charge";NativeDashEffects.Charge(p);Check(chargeMesh.enabled&&chargePS.isPlaying&&!trailMesh.enabled&&!trailPS.isPlaying&&!burstPS.isPlaying,"Charging restores only native charge art, not flight/bursts");
  NativeDashEffects.Stop(p);p.Hero.cState.superDashing=true;p.Hero.superDash.ActiveStateName="Dash";NativeDashEffects.Flight(p);Check(trailMesh.enabled&&trailPS.isPlaying&&!chargeMesh.enabled&&!chargePS.isPlaying&&!burstPS.isPlaying,"Flight restores trail without restarting crystals and one-shot particles");
  int burstStarts=burstPS.Starts;for(int i=0;i<100;i++){NativeDashEffects.Flight(p);NativeDashEffects.Tick(s);}Check(burstPS.Starts==burstStarts&&trailPS.Starts==1,"Repeated room/FX checks don't replay bursts or multiply trail emitters");
  NativeDashEffects.Stop(p);TransitionVote.Votes.Add(p);NativeDashEffects.Flight(p);Check(!trailMesh.enabled,"Room waiting cannot re-show effects");TransitionVote.Votes.Clear();
  // Another subsystem temporarily hid a renderer before FX cleanup.
  NativeDashEffects.Clear();trailMesh.enabled=false;NativeDashEffects.Stop(p);trailMesh.enabled=true;NativeDashEffects.Flight(p);Check(trailMesh.enabled,"A room-wait false snapshot cannot permanently hide a restored trail");
  NativeDashEffects.Stop(p);p.Hero.cState.superDashing=false;p.Hero.superDash.ActiveStateName="Inactive";chargeMesh.enabled=true;NativeDashEffects.Tick(s);Check(!chargeMesh.enabled,"Late native activation after cancellation is suppressed");
 }
 static void Density(){var ps=new GameObject("SD Crystals").AddComponent<ParticleSystem>();CrystalParticleDensity.Apply(ps);Check(ps.main.maxParticles==16&&ps.emission.rateOverTimeMultiplier==40,"Linked native crystal density is reduced");for(int i=0;i<100;i++)CrystalParticleDensity.Apply(ps);Check(ps.emission.rateOverTimeMultiplier==40,"Density reduction doesn't compound exponentially");CrystalParticleDensity.Restore(ps);Check(ps.main.maxParticles==100&&ps.emission.rateOverTimeMultiplier==100&&ps.emission.rateOverDistanceMultiplier==20,"Native emitter settings restore exactly");Check(CrystalDashRules.Damage(10,2)==35&&CrystalDashRules.Damage(10,3)==48&&CrystalDashRules.Damage(10,8)==55,"Existing shared crystal-dash damage multipliers stay intact");}
}
